  "questions": [
    {
      "n": 1,
      "start": "Ist es richtig, dass im Auftrag des Bundesamtes für Raumentwicklung",
      "end": "die Schweiz in drei Grossräume aufgeteilt werden soll"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Bund, Kantone, Städte und Gemeinden haben im Mai 2006 vereinbart,",
      "end": "doch weist es durchaus einen europäischen Bezug auf."
    }
  ],
  "submitter": "Franz Hostettmann",
  "co_signatories": [],
  "recommendation": "accept",
  "reasoning": {
    "start": "Der Entwurf umfasst drei Metropolitanräume (Zürich, Basel, Bassin Lémanique) und die Hauptstadtregion Bern.",
    "end": "Weder werden dadurch staatliche Strukturen verändert noch demokratische Mitwirkungsrechte oder die Autonomie der Kantone, Städte oder Gemeinden beeinträchtigt."
  }
}
